#!/bin/sh
# 复现多重定义：头文件里放变量定义
# 期望输出见 expected_output（本机 MinGW 工具链真实执行捕获）

cat > config.h << 'EOF'
#ifndef CONFIG_H
#define CONFIG_H

int counter = 0;      /* 错误示范：头文件里放定义 */

#endif
EOF

cat > main.c << 'EOF'
#include "config.h"

int main(void)
{
    counter = 1;
    return counter;
}
EOF

cat > other.c << 'EOF'
#include "config.h"

int bump(void)
{
    return ++counter;
}
EOF

gcc -c main.c -o main.o    # 各自编译都能通过
gcc -c other.c -o other.o  # 各自编译都能通过
nm main.o                  # 每个 .o 都有一份 D counter
gcc main.o other.o -o app  # 链接期才暴露：multiple definition
